def run_step(command: str, cwd: Path, env: dict, timeout: int) -> tuple[int, str]:
    bash = None
    if os.name == "nt":
        git_bash_paths = []
        git_exe = shutil.which("git")
        if git_exe:
            git_root = Path(git_exe).resolve().parent.parent
            git_bash_paths.append(git_root / "bin" / "bash.exe")
            git_bash_paths.append(git_root / "usr" / "bin" / "bash.exe")
        program_files = os.environ.get("ProgramFiles", r"C:\\Program Files")
        git_bash_paths.append(Path(program_files) / "Git" / "bin" / "bash.exe")
        program_files_x86 = os.environ.get("ProgramFiles(x86)", r"C:\\Program Files (x86)")
        git_bash_paths.append(Path(program_files_x86) / "Git" / "bin" / "bash.exe")
        for candidate in git_bash_paths:
            if candidate.is_file():
                bash = str(candidate)
                break
    if bash is None:
        candidate = shutil.which("bash")
        if candidate and "WindowsApps" not in candidate:
            bash = candidate
    if bash:
        argv = [bash, "-c", command]
    else:  # pragma: no cover - Windows without git-bash
        argv = command
    try:
        completed = subprocess.run(
            argv,
            cwd=str(cwd),
            env=env,
            capture_output=True,
            text=True,
            timeout=timeout,
            shell=not bash,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return 124, f"TIMEOUT after {timeout}s"
    output = (completed.stdout or "") + (completed.stderr or "")
    return completed.returncode, output.strip()
